#!/usr/bin/env python3
"""Print transcript records near given UTC timestamps, or human messages matching a regex.

Usage:
  tx.py FILE at TS [TS ...] [--width N]       print the records whose timestamp starts with TS
  tx.py FILE human REGEX [--from TS] [--to TS] [--width N]   human messages matching REGEX
  tx.py FILE asst REGEX [--from TS] [--to TS] [--width N]    assistant text matching REGEX
"""
import json, re, sys

def text_of(rec):
    msg = rec.get("message") or {}
    c = msg.get("content")
    if isinstance(c, str):
        return c
    out = []
    if isinstance(c, list):
        for b in c:
            if isinstance(b, dict) and b.get("type") == "text":
                out.append(b.get("text", ""))
    return "\n".join(out)

def is_human(rec):
    return rec.get("type") == "user" and (rec.get("origin") or {}).get("kind") == "human"

def main():
    path, mode = sys.argv[1], sys.argv[2]
    args = sys.argv[3:]
    width = 3000
    frm = to = None
    if "--width" in args:
        i = args.index("--width"); width = int(args[i+1]); del args[i:i+2]
    if "--from" in args:
        i = args.index("--from"); frm = args[i+1]; del args[i:i+2]
    if "--to" in args:
        i = args.index("--to"); to = args[i+1]; del args[i:i+2]
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            try:
                rec = json.loads(line)
            except Exception:
                continue
            ts = rec.get("timestamp", "")
            if frm and ts < frm: continue
            if to and ts > to: continue
            if mode == "at":
                if any(ts.startswith(t) for t in args):
                    t = text_of(rec)
                    if not t.strip(): continue
                    who = "HUMAN" if is_human(rec) else rec.get("type")
                    print(f"=== {ts} {who} ({len(t)} chars)")
                    print(t[:width])
            elif mode == "human":
                if not is_human(rec): continue
                t = text_of(rec)
                if re.search(args[0], t, re.I):
                    print(f"=== {ts} HUMAN ({len(t)} chars)")
                    print(t[:width])
            elif mode == "asst":
                if rec.get("type") != "assistant": continue
                t = text_of(rec)
                if t and re.search(args[0], t, re.I):
                    print(f"=== {ts} assistant ({len(t)} chars)")
                    print(t[:width])

if __name__ == "__main__":
    main()

